def robust(A, z):
    from scipy.linalg import lstsq
    w = np.ones(len(A))
    q = np.linalg.lstsq(A, z, rcond=None)[0]
    for _ in range(45):
        e = z - A @ q
        scale = max(3e-05, 0.8 * np.median(abs(e)))
        w = 1 / np.hypot(1, e / scale) ** 2
        q = lstsq(A * w[:, None] ** 0.5, z * w ** 0.5, lapack_driver='gelsy')[0]
    return (q, z - A @ q)

def _rosette_basis(ref, bank):
    own = ref[..., bank]
    prev = ref[..., (bank - 1) % 4]
    nxt = ref[..., (bank + 1) % 4]
    return np.stack((np.ones_like(own), own, prev, nxt, own * nxt, own ** 3), axis=-1)
